try:
    for i in range(7):
        o = observe()
        target = max(-10, min(10, 1.1 * o['route']['bearing_deg']))
        steer = max(-25, min(25, 1.95 * o['hitch_deg'] - 1.2 * target))
        n = drive(steer, -0.4, 0.6)['obs']
        if n['status'] == 'FINISHED':
            break
        if n['status'] == 'PINNED' or n['sensors']['trailer']['rear'] < 0.35:
            break
except LegOver:
    pass
print(report())

try:
    for i in range(8):
        o=observe()
        h=o['hitch_deg']
        b=o['route']['bearing_deg']
        target=max(-6,min(6,0.85*b))
        steer=max(-25,min(25,3.6*h-2.5*target))
        drive(steer,-0.25,0.5)
        if observe()['counters']['touches']>0:
            break
    print(report())
except LegOver:
    print('Leg ended.')
